// ADR-0021 r10 §16 (M5e) E6: the tree-sitter package. One archive, dist/tree-sitter-jsc-<version>.tar.gz, with the
// grammar, the parser generated by the pinned tree-sitter-cli (ADR-0018 D13 keeps it out of the repository), the
// queries, tree-sitter.json and the licence, laid out for Neovim and Helix too:
//   tree-sitter-jsc-<v>/                    grammar.js, tree-sitter.json, package.json, README.md, LICENSE, EDITORS.md
//   tree-sitter-jsc-<v>/src/                parser.c, scanner.c, grammar.json, node-types.json, tree_sitter/*.h
//   tree-sitter-jsc-<v>/queries/            highlights.scm, folds.scm (nvim-treesitter's capture names)
//   tree-sitter-jsc-<v>/neovim/queries/jsc/ the same, for a Neovim runtimepath entry
//   tree-sitter-jsc-<v>/helix/queries/jsc/  highlights.scm with Helix's capture names (its runtime/queries/jsc/)
// Every query is compiled against the grammar over the corpus (`tree-sitter query`: an unknown node or field fails),
// and the archive is reproducible: entries sorted, times, owners and modes fixed, gzip without a name or time.
//   node scripts/package.mjs [--out <dir>] [--no-generate]
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { gzipSync } from 'node:zlib';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const argv = process.argv.slice(2);
const out = argv.includes('--out') ? argv[argv.indexOf('--out') + 1] : join(root, 'dist');
const version = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')).version;
const cli = join(root, 'node_modules', '.bin', process.platform === 'win32' ? 'tree-sitter.cmd' : 'tree-sitter');
if (!existsSync(cli)) throw new Error('no tree-sitter-cli: run npm ci in tree-sitter-jsc');

const run = (args, opts = {}) => {
  const r = spawnSync(cli, args, { cwd: root, encoding: 'utf8', maxBuffer: 256 * 1024 * 1024, ...opts });
  if (r.status !== 0) throw new Error(`tree-sitter ${args.join(' ')} failed (${r.status}):\n${r.stderr}${r.stdout.slice(-2000)}`);
  return r;
};

/** Helix's capture names for nvim-treesitter's (Helix falls back along the dots; these have no common prefix). */
export const HELIX = {
  boolean: 'constant.builtin.boolean',
  number: 'constant.numeric',
  module: 'namespace',
  'keyword.conditional': 'keyword.control.conditional',
  'keyword.modifier': 'keyword.storage.modifier',
  'function.call': 'function',
  'function.method.call': 'function.method',
  'string.escape': 'constant.character.escape',
  property: 'variable.other.member',
};
export const helixQuery = (text) => text.replace(/@([a-z][a-z._]*)/g, (m, c) => (Object.hasOwn(HELIX, c) ? `@${HELIX[c]}` : m));

/** The corpus every query is compiled and run over: the valid corpus and the examples. */
function corpus() {
  const files = readdirSync(join(root, 'corpus', 'v2', 'valid')).filter((f) => f.endsWith('.jsc')).map((f) => join(root, 'corpus', 'v2', 'valid', f));
  const ex = join(root, '..', 'examples', 'dsl', 'src', 'main', 'jsc', 'org', 'julclang', 'state', 'examples', 'dsl');
  if (existsSync(ex)) for (const f of readdirSync(ex).filter((x) => x.endsWith('.jsc')).sort()) files.push(join(ex, f));
  return files;
}

/** Compiles `query` (a file) against the grammar over the corpus; throws on a query error. */
export function checkQuery(query) {
  const r = run(['query', query, ...corpus()]);
  if (/Query error|error/i.test(r.stderr.replace(/Warning: You have not configured any parser directories![\s\S]*?grammars\.\n?/, ''))) {
    throw new Error(`${query}: ${r.stderr}`);
  }
  return r.stdout.split('\n').filter((l) => l.includes('capture:')).length;
}

// ------------------------------------------------------------------ a reproducible ustar archive

function header(name, size, mode) {
  const h = Buffer.alloc(512);
  let prefix = '';
  let base = name;
  if (Buffer.byteLength(name) > 100) {
    const cut = name.lastIndexOf('/', 154);
    prefix = name.slice(0, cut);
    base = name.slice(cut + 1);
    if (Buffer.byteLength(base) > 100 || Buffer.byteLength(prefix) > 155) throw new Error(`a path too long for ustar: ${name}`);
  }
  h.write(base, 0, 100, 'utf8');
  h.write(mode.toString(8).padStart(7, '0') + '\0', 100, 8, 'ascii');
  h.write('0000000\0', 108, 8, 'ascii');            // uid
  h.write('0000000\0', 116, 8, 'ascii');            // gid
  h.write(size.toString(8).padStart(11, '0') + '\0', 124, 12, 'ascii');
  h.write('00000000000\0', 136, 12, 'ascii');       // mtime: 0
  h.write('        ', 148, 8, 'ascii');             // checksum placeholder
  h.write('0', 156, 1, 'ascii');                    // a regular file
  h.write('ustar\0', 257, 6, 'ascii');
  h.write('00', 263, 2, 'ascii');
  h.write(prefix, 345, 155, 'utf8');
  let sum = 0;
  for (const b of h) sum += b;
  h.write(sum.toString(8).padStart(6, '0') + '\0 ', 148, 8, 'ascii');
  return h;
}

export function tarGz(entries) {
  const parts = [];
  for (const [name, data] of [...entries].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))) {
    parts.push(header(name, data.length, 0o644), data, Buffer.alloc((512 - (data.length % 512)) % 512));
  }
  parts.push(Buffer.alloc(1024));
  // Level 9, no name and mtime 0 (Node writes none); the OS byte is zlib's (Unix on macOS and Linux).
  return gzipSync(Buffer.concat(parts), { level: 9 });
}

// ------------------------------------------------------------------ the package

export function build({ generate = true } = {}) {
  if (generate) run(['generate', '--abi', '14']);
  const top = `tree-sitter-jsc-${version}`;
  const files = new Map();
  const add = (rel, data) => files.set(`${top}/${rel}`, Buffer.isBuffer(data) ? data : Buffer.from(data));
  for (const f of ['grammar.js', 'tree-sitter.json', 'package.json', 'README.md']) add(f, readFileSync(join(root, f)));
  add('LICENSE', readFileSync(join(root, '..', 'LICENSE')));
  add('EDITORS.md', readFileSync(join(root, 'EDITORS.md')));
  const walk = (dir) => readdirSync(dir, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(join(dir, e.name)) : [join(dir, e.name)]));
  for (const f of walk(join(root, 'src'))) add(relative(root, f).split(sep).join('/'), readFileSync(f));
  for (const need of ['src/parser.c', 'src/scanner.c', 'src/grammar.json', 'src/node-types.json', 'src/tree_sitter/parser.h']) {
    if (!files.has(`${top}/${need}`)) throw new Error(`the package lacks ${need}`);
  }
  const queries = readdirSync(join(root, 'queries')).filter((f) => f.endsWith('.scm')).sort();
  const tmp = join(out, '.queries');
  mkdirSync(tmp, { recursive: true });
  const checked = {};
  for (const q of queries) {
    const text = readFileSync(join(root, 'queries', q), 'utf8');
    checked[q] = checkQuery(join(root, 'queries', q));
    add(`queries/${q}`, text);
    add(`neovim/queries/jsc/${q}`, text);
    // Helix: highlights only (its folds are textobjects, another query), with its capture names, compiled too.
    if (q === 'highlights.scm') {
      const hx = helixQuery(text);
      writeFileSync(join(tmp, 'helix-highlights.scm'), hx);
      checked[`helix/${q}`] = checkQuery(join(tmp, 'helix-highlights.scm'));
      add(`helix/queries/jsc/${q}`, hx);
    }
  }
  rmSync(tmp, { recursive: true, force: true });
  const archive = tarGz(files);
  return { name: `${top}.tar.gz`, archive, entries: [...files.keys()].sort(), checked, sha256: createHash('sha256').update(archive).digest('hex') };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const r = build({ generate: !argv.includes('--no-generate') });
  mkdirSync(out, { recursive: true });
  writeFileSync(join(out, r.name), r.archive);
  console.log(`${r.name}: ${r.entries.length} entries, ${r.archive.length} bytes, sha256 ${r.sha256}`);
  for (const [q, n] of Object.entries(r.checked)) console.log(`  ${q}: compiled; ${n} captures over the corpus`);
}
